  // blocks split by zeros; each block holds at most 8 values with |v| > 1, so every product stays below 2^31
  const out = [];
  while (out.length < 20000) {
    let heavy = 0;
    const len = r.int(1, 60);
    for (let i = 0; i < len; i++) {
      if (heavy < 8 && r.bool(0.2)) { heavy++; out.push(r.pick([-1, 1]) * r.int(2, 10)); }
      else out.push(r.pick([-1, 1]));
    }
    out.push(0);
  }
  return [out.slice(0, 20000)];
